import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner("{n} {p}");
        int fish = sc.nextInt();
        double price = sc.nextDouble();
        System.out.printf("一共 %d 条，花了 %.2f 元喵%n", fish, fish * price);
    }
}
